using System;using System.IO;using System.Linq;using System.Text;using System.Collections.Generic;using UnityEngine;using MashBoxSDK.AnimationStudio;using Object=UnityEngine.Object;
public static class StudioBevelReferenceExport {
 static void Dump(StudioModelDocument.Node node,string name){var s=new StringBuilder();foreach(var p in node.mesh.vertices)s.AppendLine($"v {p.x:R} {p.y:R} {p.z:R}");foreach(var f in new StudioMeshCuts(node).Faces)s.AppendLine("f "+string.Join(" ",f.Vertices.Select(i=>(i+1).ToString())));File.WriteAllText(Path.GetFullPath(Path.Combine(Application.dataPath,"../../"+name+".obj")),s.ToString());}
 public static void Export(){var source=StudioModelDocument.BuildPrimitive(PrimitiveType.Cube,out var polygons);try{var node=new StudioModelDocument.Node{mesh=source,cutPolygons=polygons,cutTriangles=source.triangles};var cuts=new StudioMeshCuts(node);var selectedFirst=cuts.Faces.SelectMany(face=>face.Vertices.Select((a,i)=>(a,face.Vertices[(i+1)%face.Vertices.Count]))).First(e=>Math.Abs(cuts.Positions[e.Item1].x-.5f)<1e-6f&&Math.Abs(cuts.Positions[e.Item2].x-.5f)<1e-6f&&Math.Abs(cuts.Positions[e.Item1].z+.5f)<1e-6f&&Math.Abs(cuts.Positions[e.Item2].z+.5f)<1e-6f);cuts.BevelEdges(node,new[]{selectedFirst},new StudioMeshCuts.BevelOptions{Width=.4f,Subdivisions=0,Tension=1});Dump(node,"sdk-reference-source");
 var path=new[]{new Vector3(.32f,.5f,-.5f),new Vector3(.32f,-.5f,-.5f),new Vector3(.5f,-.5f,-.32f),new Vector3(.5f,-.5f,.5f)};
 var top=new StudioMeshCuts(node);var all=new List<(int,int)>();foreach(var face in top.Faces)for(int i=0;i<face.Vertices.Count;i++)all.Add((face.Vertices[i],face.Vertices[(i+1)%face.Vertices.Count]));var selected=new List<(int,int)>();for(int i=0;i<3;i++){var a=path[i];var b=path[i+1];selected.Add(all.First(e=>((top.Positions[e.Item1]-a).sqrMagnitude<1e-10f&&(top.Positions[e.Item2]-b).sqrMagnitude<1e-10f)||((top.Positions[e.Item2]-a).sqrMagnitude<1e-10f&&(top.Positions[e.Item1]-b).sqrMagnitude<1e-10f)));}
 foreach(float width in new[]{.074f,.449f,1f}){var mesh=Object.Instantiate(source);try{var output=new StudioModelDocument.Node{mesh=mesh,cutPolygons=node.cutPolygons,cutTriangles=node.cutTriangles,normalGroups=node.normalGroups};new StudioMeshCuts(output).BevelEdges(output,selected,new StudioMeshCuts.BevelOptions{Width=width,Subdivisions=0,Tension=1});var result=new StudioMeshCuts(output);if(result.Positions.Distinct().Count()!=14||result.Faces.Count!=10||result.Faces.Any(face=>face.Vertices.Count<4))throw new Exception("Sequential bevel retained an extra corner facet at width "+width);foreach(var face in result.Faces){var origin=result.Positions[face.Vertices[0]];var normal=Vector3.zero;for(int i=1;i+1<face.Vertices.Count;i++)normal+=Vector3.Cross(result.Positions[face.Vertices[i]]-origin,result.Positions[face.Vertices[i+1]]-origin);normal.Normalize();foreach(int vertex in face.Vertices)if(Math.Abs(Vector3.Dot(normal,result.Positions[vertex]-origin))>2e-6)throw new Exception("Sequential straight chamfer face warped");}Dump(output,"sdk-reference-"+width);}finally{Object.DestroyImmediate(mesh);}}
 }finally{if(source)Object.DestroyImmediate(source);}}
}
